def dt(*args):
    return datetime(*args)


class NextRunTests(unittest.TestCase):
    # "The first minute strictly after `after`"
    def test_strictly_after_exact_match_skipped(self):
        self.assertEqual(next_run("0 10 * * *", dt(2026, 10, 11, 10, 0)), dt(2026, 10, 12, 10, 0))

    def test_next_minute_when_every_minute(self):
        self.assertEqual(next_run("* * * * *", dt(2026, 10, 11, 10, 0)), dt(2026, 10, 11, 10, 1))

    def test_seconds_dropped_before_comparison(self):
        # 10:00:30 truncates to 10:00, so the next minute is 10:01
        self.assertEqual(next_run("* * * * *", dt(2026, 10, 11, 10, 0, 30)), dt(2026, 10, 11, 10, 1))

    def test_microseconds_dropped_before_comparison(self):
        self.assertEqual(next_run("* * * * *", dt(2026, 10, 11, 10, 0, 0, 500)), dt(2026, 10, 11, 10, 1))

    def test_result_is_naive(self):
        self.assertIsNone(next_run("* * * * *", dt(2026, 10, 11, 10, 0)).tzinfo)

    # "five fields separated by single spaces"
    def test_wrong_field_count_raises(self):
        for bad in ["* * * *", "* * * * * *", ""]:
            with self.subTest(bad=bad), self.assertRaises(ValueError):
                next_run(bad, dt(2026, 1, 1))

    def test_double_space_raises(self):
        with self.assertRaises(ValueError):
            next_run("0  10 * * *", dt(2026, 1, 1))

    def test_leading_or_trailing_space_raises(self):
        for bad in [" 0 10 * * *", "0 10 * * * "]:
            with self.subTest(bad=bad), self.assertRaises(ValueError):
                next_run(bad, dt(2026, 1, 1))

    # ranges per field
    def test_out_of_range_values_raise(self):
        bad = ["60 * * * *", "* 24 * * *", "* * 0 * *", "* * 32 * *",
               "* * * 0 *", "* * * 13 *", "* * * * 8", "-1 * * * *"]
        for expr in bad:
            with self.subTest(expr=expr), self.assertRaises(ValueError):
                next_run(expr, dt(2026, 1, 1))

    def test_boundary_values_accepted(self):
        next_run("59 23 31 12 6", dt(2026, 1, 1))
        next_run("0 0 1 1 0", dt(2026, 1, 1))

    # field forms: *, number, a-b, */n, a-b/n, comma list
    def test_step(self):
        self.assertEqual(next_run("*/15 * * * *", dt(2026, 10, 11, 10, 0)), dt(2026, 10, 11, 10, 15))

    def test_range_with_step(self):
        # 5-10/2 -> minutes 5, 7, 9
        self.assertEqual(next_run("5-10/2 * * * *", dt(2026, 10, 11, 10, 0)), dt(2026, 10, 11, 10, 5))
        self.assertEqual(next_run("5-10/2 * * * *", dt(2026, 10, 11, 10, 6)), dt(2026, 10, 11, 10, 7))

    def test_comma_list(self):
        self.assertEqual(next_run("1,30 * * * *", dt(2026, 10, 11, 10, 2)), dt(2026, 10, 11, 10, 30))

    def test_comma_list_mixing_forms(self):
        self.assertEqual(next_run("0-5,*/20 * * * *", dt(2026, 10, 11, 10, 7)), dt(2026, 10, 11, 10, 20))

    def test_malformed_fields_raise(self):
        bad = ["5/10 * * * *",       # step on a bare number
               "*/0 * * * *",        # zero step
               "10-5 * * * *",       # backwards range
               "1,,2 * * * *",       # empty list item
               "*-5 * * * *",
               "a * * * *",
               "1.5 * * * *",
               "-5 * * * *",
               "* * * * */"]
        for expr in bad:
            with self.subTest(expr=expr), self.assertRaises(ValueError):
                next_run(expr, dt(2026, 1, 1))

    # names: months JAN-DEC, days SUN-SAT, any case, inside ranges too
    def test_month_name(self):
        self.assertEqual(next_run("0 0 1 jan *", dt(2026, 10, 11)), dt(2027, 1, 1))

    def test_month_name_range(self):
        self.assertEqual(next_run("0 0 1 SEP-DEC *", dt(2026, 1, 1)), dt(2026, 9, 1))

    def test_dow_name_range_case_insensitive(self):
        # 2026-10-11 is a Sunday; MON-FRI next hit is Monday 2026-10-12
        self.assertEqual(next_run("0 9 * * mon-FRI", dt(2026, 10, 11, 10, 0)), dt(2026, 10, 12, 9, 0))

    def test_dow_names_in_list(self):
        self.assertEqual(next_run("0 0 * * WED,sat", dt(2026, 10, 11)), dt(2026, 10, 14))

    def test_names_in_wrong_field_raise(self):
        with self.assertRaises(ValueError):
            next_run("0 0 * FRI *", dt(2026, 1, 1))
        with self.assertRaises(ValueError):
            next_run("JAN 0 * * *", dt(2026, 1, 1))

    def test_unknown_name_raises(self):
        with self.assertRaises(ValueError):
            next_run("0 0 * * FUN", dt(2026, 1, 1))

    # SUN is 0; 7 is also Sunday
    def test_seven_is_sunday(self):
        self.assertEqual(next_run("0 0 * * 7", dt(2026, 10, 11)), next_run("0 0 * * 0", dt(2026, 10, 11)))
        self.assertEqual(next_run("0 0 * * 7", dt(2026, 10, 11)), dt(2026, 10, 18))

    def test_range_ending_in_seven(self):
        # 5-7 is Fri, Sat, Sun
        self.assertEqual(next_run("0 0 * * 5-7", dt(2026, 10, 12)), dt(2026, 10, 16))
        self.assertEqual(next_run("0 0 * * 5-7", dt(2026, 10, 17)), dt(2026, 10, 17))

    # day-of-month OR day-of-week when both restricted
    def test_dom_or_dow_when_both_restricted(self):
        # 2026-10-02 is a Friday, 2026-10-13 is the 13th; Friday comes first
        self.assertEqual(next_run("0 0 13 * FRI", dt(2026, 10, 1)), dt(2026, 10, 2))
        # from Oct 3 the next hit is the 13th (a Tuesday)
        self.assertEqual(next_run("0 0 13 * FRI", dt(2026, 10, 3)), dt(2026, 10, 9))
        self.assertEqual(next_run("0 0 13 * FRI", dt(2026, 10, 9)), dt(2026, 10, 13))

    def test_dom_only_when_dow_is_star(self):
        # Fridays must not count when dow is *
        self.assertEqual(next_run("0 0 13 * *", dt(2026, 10, 1)), dt(2026, 10, 13))

    def test_dow_only_when_dom_is_star(self):
        self.assertEqual(next_run("0 0 * * FRI", dt(2026, 10, 3)), dt(2026, 10, 9))

    # time-of-day and calendar rollover
    def test_month_rollover(self):
        self.assertEqual(next_run("0 0 1 * *", dt(2026, 10, 11)), dt(2026, 11, 1))

    def test_year_rollover(self):
        self.assertEqual(next_run("0 0 1 1 *", dt(2026, 10, 11)), dt(2027, 1, 1))

    def test_hour_rollover(self):
        self.assertEqual(next_run("5 3 * * *", dt(2026, 10, 11, 3, 5)), dt(2026, 10, 12, 3, 5))

