    def test_leap_day(self):
        self.assertEqual(next_run("0 0 29 2 *", dt(2026, 3, 1)), dt(2028, 2, 29))

    def test_impossible_date_raises(self):
        with self.assertRaises(ValueError):
            next_run("0 0 31 2 *", dt(2026, 1, 1))


